window.docContents[33].resolve({"/Abstraction/Function-and-program/#Core-C______--Abstraction--Function-and-program":{"contents":"A function is well typed when its body is, under the context of its parameters and its return type.\n\nA program is a list of functions with distinct names and a function int main(). The initial store is empty, because there are no global variables, and the result is the value of main().\n\n","context":"Core C++\u0009Abstraction","header":"5.5. Function and program","id":"/Abstraction/Function-and-program/#Core-C______--Abstraction--Function-and-program"}});